INSERT INTO module_questions (module_id, level, question, options, correct_index, explanation, xp_reward) VALUES
('cpu-boss','basic','What does CPU stand for?',ARRAY['Central Processing Unit','Computer Processing Unit','Central Power Unit','Computer Power Unit'],0,'CPU = Central Processing Unit.',10),
('cpu-boss','basic','What is the function of a CPU?',ARRAY['Executes instructions','Stores data','Displays output','Powers the computer'],0,'CPU fetches, decodes, and executes instructions.',10),
('cpu-boss','basic','What are the main parts of a CPU?',ARRAY['ALU, Control Unit, Registers','Cache and RAM','Hard drive and SSD','Input and output'],0,'CPU: ALU (compute), CU (control), Registers (storage).',10),
('cpu-boss','basic','What does ALU stand for?',ARRAY['Arithmetic Logic Unit','Advanced Logic Unit','Arithmetic Loading Unit','Active Logic Unit'],0,'ALU performs arithmetic and logical operations.',10),
('cpu-boss','basic','What does the Control Unit do?',ARRAY['Directs operation of the CPU','Performs calculations','Stores data','Manages memory'],0,'CU generates control signals for other components.',10),
('cpu-boss','basic','What are registers?',ARRAY['Small fast storage in CPU','Main memory','Cache memory','Disk storage'],0,'Registers: fastest, smallest storage in the CPU.',10),
('cpu-boss','basic','What is the program counter (PC)?',ARRAY['Holds address of next instruction','Counts programs','Counts clock cycles','Counts registers'],0,'PC points to the next instruction to fetch.',10),
('cpu-boss','basic','What is the instruction register (IR)?',ARRAY['Holds current instruction','Holds next instruction','Holds data','Holds address'],0,'IR stores the currently executing instruction.',10),
('cpu-boss','basic','What is the fetch-decode-execute cycle?',ARRAY['Basic CPU operation cycle','Memory cycle','I/O cycle','Cache cycle'],0,'Fetch: get instruction. Decode: interpret. Execute: perform.',10),
('cpu-boss','basic','What is a clock cycle?',ARRAY['One tick of the CPU clock','One instruction','One memory access','One I/O operation'],0,'Clock cycle = basic time unit for CPU operations.',10),
('cpu-boss','basic','What is clock speed measured in?',ARRAY['Hertz (Hz)','Bytes','Volts','Watts'],0,'Clock speed in Hz (GHz for modern CPUs).',10),
('cpu-boss','basic','What is the word size of a CPU?',ARRAY['Number of bits processed in one operation','Clock frequency','Cache size','Number of registers'],0,'Word size: 8, 16, 32, or 64 bits typically.',10),
('cpu-boss','basic','What is a 32-bit CPU?',ARRAY['Processes 32 bits at a time','Has 32 registers','Runs at 32 Hz','Has 32 pins'],0,'32-bit CPU: 32-bit data bus and registers.',10),
('cpu-boss','basic','What is a 64-bit CPU?',ARRAY['Processes 64 bits at a time','Has 64 registers','Runs at 64 Hz','Has 64 pins'],0,'64-bit CPU: 64-bit data bus and registers.',10),
('cpu-boss','basic','What is cache memory?',ARRAY['Fast memory between CPU and RAM','Slow memory','Disk storage','Flash memory'],0,'Cache: L1/L2/L3, faster than RAM, smaller.',10),
('cpu-boss','basic','What is L1 cache?',ARRAY['Closest and fastest cache to CPU','Largest cache','Disk cache','Network cache'],0,'L1: smallest, fastest, per-core.',10),
('cpu-boss','basic','What is the difference between L1 and L2 cache?',ARRAY['L1 is faster and smaller than L2','L2 is faster','Same speed','L1 is larger'],0,'L1 < L2 < L3 in size, L1 > L2 > L3 in speed.',10),
('cpu-boss','basic','What is a pipeline in a CPU?',ARRAY['Overlapping instruction execution','Memory pipeline','Cache pipeline','I/O pipeline'],0,'Pipelining: multiple instructions in different stages simultaneously.',10),
('cpu-boss','basic','What are the basic pipeline stages?',ARRAY['Fetch, Decode, Execute, Memory, Write-back','Read, Write','Input, Output','Load, Store'],0,'Classic 5-stage MIPS pipeline: IF, ID, EX, MEM, WB.',10),
('cpu-boss','basic','What is instruction latency?',ARRAY['Time to complete one instruction','Number of instructions','Clock speed','Cache size'],0,'Latency = cycles per individual instruction.',10),
('cpu-boss','basic','What is throughput in a CPU?',ARRAY['Instructions completed per unit time','Clock frequency','Memory size','Cache size'],0,'Throughput = IPC × clock frequency.',10),
('cpu-boss','basic','What is IPC?',ARRAY['Instructions Per Cycle','Instructions Per Clock-cycle','Internal Process Counter','Input Process Control'],0,'IPC: average instructions completed per clock cycle.',10),
('cpu-boss','basic','What is a register file?',ARRAY['Collection of registers in CPU','File in memory','Cache file','Disk file'],0,'Register file: small array of fast registers.',10),
('cpu-boss','basic','What is a bus?',ARRAY['Communication path between components','A type of memory','A cache type','A register'],0,'Buses transfer data between CPU, memory, I/O.',10),
('cpu-boss','basic','What is the data bus?',ARRAY['Carries data between components','Carries addresses','Carries control signals','Carries clock'],0,'Data bus width = word size.',10),
('cpu-boss','basic','What is the address bus?',ARRAY['Carries memory addresses','Carries data','Carries control signals','Carries clock'],0,'Address bus width determines addressable memory.',10),
('cpu-boss','basic','What is the control bus?',ARRAY['Carries control signals','Carries data','Carries addresses','Carries power'],0,'Control bus: read/write, interrupt, clock signals.',10),
('cpu-boss','basic','How many addressable locations with a 16-bit address bus?',ARRAY['65536','32768','16384','256'],0,'2^16 = 65536 locations.',10),
('cpu-boss','basic','How much memory can a 32-bit address bus address?',ARRAY['4 GB','2 GB','1 GB','8 GB'],0,'2^32 = 4,294,967,296 bytes = 4 GB.',10),
('cpu-boss','basic','What is RAM?',ARRAY['Random Access Memory','Read Access Memory','Rapid Access Memory','Random Active Memory'],0,'RAM: volatile, fast read/write memory.',10),
('cpu-boss','basic','What is ROM?',ARRAY['Read-Only Memory','Random Output Memory','Read-Only Module','Rapid Output Memory'],0,'ROM: non-volatile, permanent storage.',10),
('cpu-boss','basic','What is the difference between RAM and ROM?',ARRAY['RAM is volatile, ROM is non-volatile','RAM is faster','ROM is larger','No difference'],0,'RAM loses data on power off; ROM retains data.',10),
('cpu-boss','basic','What is an instruction set?',ARRAY['Set of all instructions a CPU can execute','Set of registers','Set of buses','Set of memories'],0,'ISA (Instruction Set Architecture) defines CPU operations.',10),
('cpu-boss','basic','What is an opcode?',ARRAY['Operation code specifying the instruction','Address of data','Register number','Memory location'],0,'Opcode: tells CPU what operation to perform.',10),
('cpu-boss','basic','What is an operand?',ARRAY['Data or address for the instruction','Operation code','Register name','Clock cycle'],0,'Operand: the data the instruction operates on.',10),
('cpu-boss','basic','What is assembly language?',ARRAY['Low-level programming using mnemonics','High-level language','Machine language','Natural language'],0,'Assembly: human-readable, one-to-one with machine code.',10),
('cpu-boss','basic','What is machine code?',ARRAY['Binary instructions executed by CPU','Assembly language','High-level code','Source code'],0,'Machine code: 1s and 0s, directly executed by hardware.',10),
('cpu-boss','basic','What is a RISC architecture?',ARRAY['Reduced Instruction Set Computer','Random Instruction Set Computer','Rapid Instruction Set Computer','Regular Instruction Set Computer'],0,'RISC: simple, fixed-length instructions, many registers.',10),
('cpu-boss','basic','What is a CISC architecture?',ARRAY['Complex Instruction Set Computer','Compact Instruction Set Computer','Complete Instruction Set Computer','Common Instruction Set Computer'],0,'CISC: complex, variable-length instructions (e.g., x86).',10),
('cpu-boss','basic','Which is a RISC architecture?',ARRAY['ARM','x86','Intel Core','AMD Ryzen'],0,'ARM is RISC; x86 is CISC.',10),
('cpu-boss','basic','Which is a CISC architecture?',ARRAY['x86','ARM','MIPS','RISC-V'],0,'x86 is CISC; ARM, MIPS, RISC-V are RISC.',10),
('cpu-boss','basic','What is a core in a CPU?',ARRAY['Independent processing unit','Cache unit','Memory unit','Bus unit'],0,'Multi-core CPUs have multiple independent processing units.',10),
('cpu-boss','basic','What is a multi-core CPU?',ARRAY['CPU with multiple processing cores','CPU with multiple caches','CPU with multiple buses','CPU with multiple registers'],0,'Multi-core: parallel execution on same chip.',10),
('cpu-boss','basic','What is hyper-threading?',ARRAY['Simulating two cores on one physical core','Doubling clock speed','Doubling cache','Doubling registers'],0,'SMT (Simultaneous Multi-Threading): 2 threads per core.',10),
('cpu-boss','basic','What is an interrupt?',ARRAY['Signal that pauses CPU execution','A type of instruction','A memory access','A clock signal'],0,'Interrupts allow external devices to request CPU attention.',10),
('cpu-boss','basic','What is an interrupt handler?',ARRAY['Routine that processes an interrupt','A type of register','A memory location','A bus signal'],0,'ISR (Interrupt Service Routine) handles the interrupt.',10),
('cpu-boss','basic','What is DMA?',ARRAY['Direct Memory Access','Direct Memory Address','Data Memory Access','Dynamic Memory Allocation'],0,'DMA: peripheral transfers data to memory without CPU.',10),
('cpu-boss','basic','What is the advantage of DMA?',ARRAY['CPU is free during data transfer','Faster clock','More memory','More registers'],0,'DMA offloads data transfer from CPU.',10),
('cpu-boss','basic','What is a flag register?',ARRAY['Holds status flags from operations','Holds data','Holds addresses','Holds instructions'],0,'Flags: zero, carry, sign, overflow, parity.',10),
('cpu-boss','basic','What is the zero flag?',ARRAY['Set when result is zero','Set when result is negative','Set when overflow occurs','Set when carry occurs'],0,'Zero flag = 1 when ALU result is 0.',10);INSERT INTO module_questions (module_id, level, question, options, correct_index, explanation, xp_reward) VALUES
('cpu-boss','intermediate','What is a pipeline hazard?',ARRAY['Situation preventing next instruction from executing','Pipeline overflow','Cache miss','Bus error'],0,'Hazards: structural, data, control.',15),
('cpu-boss','intermediate','What is a structural hazard?',ARRAY['Resource conflict (same hardware needed)','Data dependency','Branch instruction','Cache miss'],0,'Structural: two instructions need same hardware simultaneously.',15),
('cpu-boss','intermediate','What is a data hazard?',ARRAY['Dependence between instructions','Resource conflict','Branch prediction','Cache miss'],0,'Data hazards: RAW, WAW, WAR dependencies.',15),
('cpu-boss','intermediate','What is a RAW hazard?',ARRAY['Read After Write: need result of previous instruction','Read After Write conflict','Random Access Write','Register Address Write'],0,'RAW: instruction reads before previous write completes.',15),
('cpu-boss','intermediate','What is a WAW hazard?',ARRAY['Write After Write: two writes to same register','Write After Write conflict','Write After Wait','Word Address Write'],0,'WAW: out-of-order execution can cause wrong final value.',15),
('cpu-boss','intermediate','What is a WAR hazard?',ARRAY['Write After Read: write before previous read','Write After Read conflict','Word After Read','Write Access Register'],0,'WAR: writing before previous instruction reads old value.',15),
('cpu-boss','intermediate','How do you resolve data hazards?',ARRAY['Forwarding/bypassing or stalling','Adding more registers','Increasing clock','Adding cache'],0,'Forwarding: pass result directly to next instruction.',15),
('cpu-boss','intermediate','What is forwarding (bypassing)?',ARRAY['Passing result directly without waiting for writeback','Adding more cache','Increasing clock speed','Adding pipelines'],0,'Forwarding: ALU result sent directly to next instruction.',15),
('cpu-boss','intermediate','What is a pipeline stall (bubble)?',ARRAY['Inserting NOP cycles to resolve hazards','Adding more instructions','Removing instructions','Increasing clock'],0,'Stall: pause pipeline until hazard resolves.',15),
('cpu-boss','intermediate','What is a control hazard?',ARRAY['Branch/change in control flow','Data dependency','Resource conflict','Cache miss'],0,'Control hazards: branches change flow, pipeline unsure.',15),
('cpu-boss','intermediate','How do you reduce control hazards?',ARRAY['Branch prediction and delay slots','More cache','More registers','Higher clock'],0,'Prediction: guess branch direction to keep pipeline full.',15),
('cpu-boss','intermediate','What is branch prediction?',ARRAY['Guessing branch outcome before resolution','Counting branches','Removing branches','Adding branches'],0,'Prediction: minimize stalls from control hazards.',15),
('cpu-boss','intermediate','What is static branch prediction?',ARRAY['Fixed prediction (e.g., always not taken)','Prediction based on history','Prediction based on cache','No prediction'],0,'Static: simple heuristic (backward = taken).',15),
('cpu-boss','intermediate','What is dynamic branch prediction?',ARRAY['Prediction based on execution history','Fixed prediction','No prediction','Random prediction'],0,'Dynamic: BHT, BTB, perceptron predictors.',15),
('cpu-boss','intermediate','What is a branch target buffer (BTB)?',ARRAY['Cache storing branch target addresses','Branch predictor cache','Data cache','Instruction cache'],0,'BTB: stores target address for recent branches.',15),
('cpu-boss','intermediate','What is a branch history table (BHT)?',ARRAY['Table storing branch outcome history','Target addresses','Instruction cache','Data cache'],0,'BHT: 1-bit or 2-bit saturating counters per branch.',15),
('cpu-boss','intermediate','What is a 2-bit saturating counter predictor?',ARRAY['Strong/weak taken/not-taken states','1-bit predictor','No prediction','Random'],0,'2-bit: more stable, tolerates one misprediction.',15),
('cpu-boss','intermediate','What is a branch delay slot?',ARRAY['Instruction after branch always executes','Instruction before branch','Skipped instruction','NOP instruction'],0,'Delay slot: MIPS executes next instruction regardless.',15),
('cpu-boss','intermediate','What is speculative execution?',ARRAY['Executing instructions before knowing if needed','Executing after branch resolves','Not executing','Random execution'],0,'Speculation: execute predicted path, flush if wrong.',15),
('cpu-boss','intermediate','What is out-of-order execution?',ARRAY['Executing instructions when ready, not in order','Executing in order','Not executing','Random order'],0,'OoO: improves ILP by using available resources.',15),
('cpu-boss','intermediate','What is instruction-level parallelism (ILP)?',ARRAY['Executing multiple instructions simultaneously','Parallel cores','Parallel threads','Parallel cache'],0,'ILP: pipelining + superscalar + OoO + speculation.',15),
('cpu-boss','intermediate','What is a superscalar CPU?',ARRAY['Multiple execution units per cycle','Single execution unit','No pipeline','Single core'],0,'Superscalar: >1 instruction per cycle (multiple ALUs).',15),
('cpu-boss','intermediate','What is VLIW?',ARRAY['Very Long Instruction Word','Very Large Internal Word','Variable Length Instruction Word','Virtual Linear Instruction Word'],0,'VLIW: compiler packs multiple ops into one wide instruction.',15),
('cpu-boss','intermediate','What is the difference between VLIW and superscalar?',ARRAY['VLIW: compiler schedules; superscalar: hardware schedules','No difference','VLIW is faster','Superscalar is simpler'],0,'VLIW relies on compiler; superscalar has dynamic scheduling.',15),
('cpu-boss','intermediate','What is SIMD?',ARRAY['Single Instruction Multiple Data','Single Input Multiple Devices','Simple Instruction Multiple Data','Single Instruction Memory Data'],0,'SIMD: one instruction operates on multiple data elements.',15),
('cpu-boss','intermediate','What is an example of SIMD?',ARRAY['Intel SSE/AVX','Hyper-threading','Multi-core','Pipeline'],0,'SSE/AVX: vector operations on multiple data.',15),
('cpu-boss','intermediate','What is vector processing?',ARRAY['Operating on arrays of data with one instruction','Scalar processing','Branch prediction','Cache optimization'],0,'Vector: GPU and CPU SIMD extensions.',15),
('cpu-boss','intermediate','What is SMT?',ARRAY['Simultaneous Multi-Threading','Single Multi-Thread','Synchronous Multi-Threading','Sequential Multi-Thread'],0,'SMT: multiple threads share one core''s resources.',15),
('cpu-boss','intermediate','What is a thread in CPU context?',ARRAY['Independent sequence of instructions','A core','A cache line','A register'],0,'Threads share core resources but have independent state.',15),
('cpu-boss','intermediate','What is a context switch?',ARRAY['Saving and restoring CPU state for thread/process','Switching cache','Switching clock','Switching bus'],0,'Context switch: save PC, registers, switch to new thread.',15),
('cpu-boss','intermediate','What is virtual memory?',ARRAY['Using disk as extended RAM','Cache memory','Register memory','ROM memory'],0,'Virtual memory: page table maps virtual to physical addresses.',15),
('cpu-boss','intermediate','What is a page table?',ARRAY['Maps virtual to physical addresses','Maps cache to memory','Maps registers to memory','Maps buses to devices'],0,'Page table: OS-managed, translates virtual addresses.',15),
('cpu-boss','intermediate','What is a TLB?',ARRAY['Translation Lookaside Buffer','Table Lookaside Buffer','Translation Logic Buffer','Table Logic Buffer'],0,'TLB: cache for page table entries (speeds translation).',15),
('cpu-boss','intermediate','What is a TLB miss?',ARRAY['Translation not found in TLB','Cache miss','Page fault','Bus error'],0,'TLB miss: walk page table to find translation.',15),
('cpu-boss','intermediate','What is a page fault?',ARRAY['Access to page not in physical memory','TLB miss','Cache miss','Bus error'],0,'Page fault: OS must load page from disk.',15),
('cpu-boss','intermediate','What is cache coherence?',ARRAY['Multiple caches agree on memory values','Cache speed','Cache size','Cache replacement'],0,'Coherence: ensures all cores see consistent data.',15),
('cpu-boss','intermediate','What is MESI protocol?',ARRAY['Cache coherence protocol (Modified, Exclusive, Shared, Invalid)','Memory protocol','Bus protocol','Clock protocol'],0,'MESI: 4-state protocol for multi-core cache coherence.',15),
('cpu-boss','intermediate','What is a cache hit?',ARRAY['Requested data found in cache','Data not in cache','Data in memory','Data in disk'],0,'Cache hit: data available without accessing main memory.',15),
('cpu-boss','intermediate','What is a cache miss?',ARRAY['Requested data not in cache','Data in cache','Data in register','Data in TLB'],0,'Cache miss: must fetch from lower memory hierarchy.',15),
('cpu-boss','intermediate','What are the three types of cache misses?',ARRAY['Compulsory, Capacity, Conflict','Read, Write, Execute','L1, L2, L3','Data, Instruction, TLB'],0,'3Cs: Compulsory (cold), Capacity, Conflict.',15),
('cpu-boss','intermediate','What is a compulsory miss?',ARRAY['First access to data (never cached)','Cache full','Multiple map to same set','Cache too small'],0,'Compulsory: unavoidable first-time miss.',15),
('cpu-boss','intermediate','What is a capacity miss?',ARRAY['Cache cannot hold all active data','First access','Conflict in set','Coherence'],0,'Capacity: cache too small for working set.',15),
('cpu-boss','intermediate','What is a conflict miss?',ARRAY['Multiple addresses map to same cache set','First access','Cache too small','Coherence issue'],0,'Conflict: limited associativity causes evictions.',15),
('cpu-boss','intermediate','What is cache associativity?',ARRAY['Number of locations data can be placed','Cache size','Cache speed','Cache replacement'],0,'Direct-mapped, set-associative, fully-associative.',15),
('cpu-boss','intermediate','What is a direct-mapped cache?',ARRAY['Each address maps to one cache line','Multiple locations per address','Any location','No mapping'],0,'Direct-mapped: simple, fast, more conflict misses.',15),
('cpu-boss','intermediate','What is a fully-associative cache?',ARRAY['Data can go in any cache line','One location per address','Fixed location','No mapping'],0,'Fully-associative: flexible, fewer misses, more complex.',15),
('cpu-boss','intermediate','What is a set-associative cache?',ARRAY['Data maps to a set of N lines','One line per address','Any line','No mapping'],0,'N-way set-associative: compromise between direct and full.',15),
('cpu-boss','intermediate','What is a cache line (block)?',ARRAY['Minimum unit of cache transfer','Single byte','Single word','Cache set'],0,'Cache line: typically 32-64 bytes, fetched together.',15),
('cpu-boss','intermediate','What is a write-through cache?',ARRAY['Writes to cache and memory simultaneously','Writes to cache only','Writes to memory only','No writes'],0,'Write-through: simple, consistent, more memory traffic.',15),
('cpu-boss','intermediate','What is a write-back cache?',ARRAY['Writes to cache, memory updated later','Writes to both','Writes to memory only','No writes'],0,'Write-back: efficient, dirty bit tracks changes.',15);INSERT INTO module_questions (module_id, level, question, options, correct_index, explanation, xp_reward) VALUES
('cpu-boss','advanced','What is Tomasulo''s algorithm?',ARRAY['Dynamic scheduling with reservation stations','Branch prediction','Cache coherence','Pipeline stalling'],0,'Tomasulo: register renaming, RS, common data bus.',20),
('cpu-boss','advanced','What is register renaming?',ARRAY['Mapping architectural to physical registers','Removing registers','Adding registers','Cache mapping'],0,'Renaming eliminates WAW and WAR hazards.',20),
('cpu-boss','advanced','What is a reorder buffer (ROB)?',ARRAY['Enables in-order commit of OoO instructions','Branch predictor','Cache buffer','Memory buffer'],0,'ROB: instructions execute OoO but commit in order.',20),
('cpu-boss','advanced','What is a reservation station?',ARRAY['Holds instruction until operands ready','Cache line','Register file','Memory buffer'],0,'RS: waiting area for instructions in Tomasulo.',20),
('cpu-boss','advanced','What is a common data bus (CDB)?',ARRAY['Broadcasts results to all reservation stations','Memory bus','Address bus','Control bus'],0,'CDB: results broadcast to waiting RS in one cycle.',20),
('cpu-boss','advanced','What is the difference between scoreboarding and Tomasulo?',ARRAY['Tomasulo uses renaming; scoreboarding uses stalls','No difference','Scoreboarding is faster','Tomasulo is simpler'],0,'Scoreboarding: stalls on WAW/WAR. Tomasulo: renaming avoids them.',20),
('cpu-boss','advanced','What is a load-store queue (LSQ)?',ARRAY['Manages memory operations in OoO execution','Cache queue','Bus queue','Register queue'],0,'LSQ: handles load/store ordering, memory disambiguation.',20),
('cpu-boss','advanced','What is memory disambiguation?',ARRAY['Determining if load/store access same address','Cache replacement','TLB management','Bus arbitration'],0,'Disambiguation: can load bypass earlier store?',20),
('cpu-boss','advanced','What is a store buffer?',ARRAY['Holds stores until commit','Cache buffer','Register buffer','Bus buffer'],0,'Store buffer: stores commit in order, not visible until retired.',20),
('cpu-boss','advanced','What is speculative load execution?',ARRAY['Executing loads before branch resolves','Cache loading','Register loading','Bus loading'],0,'Speculative loads: may need rollback if path wrong.',20),
('cpu-boss','advanced','What is a micro-op (µop)?',ARRAY['Simple operations decomposing complex instructions','Macro instruction','Cache operation','Bus operation'],0,'CISC instructions decoded into µops (like RISC).',20),
('cpu-boss','advanced','What is a trace cache?',ARRAY['Cache storing decoded µops','Data cache','Instruction cache','TLB cache'],0,'Trace cache: stores decoded instruction sequences (P4).',20),
('cpu-boss','advanced','What is microcode?',ARRAY['Low-level code implementing complex instructions','Assembly code','Machine code','High-level code'],0,'Microcode: ROM-based routines for complex instructions.',20),
('cpu-boss','advanced','What is the difference between hardwired and microcoded control?',ARRAY['Hardwired: fast, fixed; microcoded: slow, flexible','No difference','Hardwired is slower','Microcoded is faster'],0,'Hardwired: FSM logic. Microcoded: ROM lookup.',20),
('cpu-boss','advanced','What is a superscalar issue width?',ARRAY['Number of instructions issued per cycle','Number of pipelines','Number of cores','Number of registers'],0,'Issue width: 2, 4, 6, 8 instructions per cycle.',20),
('cpu-boss','advanced','What is an instruction window?',ARRAY['Set of instructions available for OoO execution','Cache window','Register window','Bus window'],0,'Larger window = more ILP exploited.',20),
('cpu-boss','advanced','What is the difference between issue and dispatch?',ARRAY['Issue: send to RS; dispatch: execute when ready','No difference','Issue is execution','Dispatch is fetch'],0,'Issue: to reservation station. Dispatch: to execution unit.',20),
('cpu-boss','advanced','What is commit (retire)?',ARRAY['Permanently updating state after execution','Fetching instructions','Decoding instructions','Executing instructions'],0,'Commit: in-order, updates registers/memory.',20),
('cpu-boss','advanced','What is a precise exception?',ARRAY['All prior instructions committed, none after','All instructions committed','No instructions committed','Random state'],0,'Precise: clean state for interrupt handling.',20),
('cpu-boss','advanced','What is instruction fusion?',ARRAY['Combining two instructions into one µop','Splitting instructions','Removing instructions','Adding instructions'],0,'Fusion: e.g., compare+branch fused into one op.',20),
('cpu-boss','advanced','What is macro-operation fusion?',ARRAY['Combining macro-instructions at decode','Combining µops','Removing µops','Splitting µops'],0,'Macro-fusion: e.g., CMP + JCC → one µop (Intel).',20),
('cpu-boss','advanced','What is a µop cache?',ARRAY['Cache of decoded µops before decode stage','Data cache','Instruction cache','TLB'],0,'µop cache: skips decode for repeated code (Intel Sandy Bridge+).',20),
('cpu-boss','advanced','What is the front-end of a CPU pipeline?',ARRAY['Fetch + decode stages','Execute stage','Memory stage','Writeback stage'],0,'Front-end: fetch, decode, branch prediction.',20),
('cpu-boss','advanced','What is the back-end of a CPU pipeline?',ARRAY['Execute + memory + writeback','Fetch + decode','Branch prediction','Cache only'],0,'Back-end: execution units, memory, commit.',20),
('cpu-boss','advanced','What is a decode queue?',ARRAY['Buffer between decode and rename stages','Cache queue','Bus queue','Memory queue'],0,'Decode queue: smooths front-end to back-end flow.',20),
('cpu-boss','advanced','What is the rename stage?',ARRAY['Maps architectural to physical registers','Decode stage','Fetch stage','Execute stage'],0,'Rename: allocates physical registers, removes false deps.',20),
('cpu-boss','advanced','What is a physical register file?',ARRAY['Actual storage with more registers than ISA defines','ISA registers only','Cache','Memory'],0,'PRF: e.g., 128-256 physical vs 16-32 architectural.',20),
('cpu-boss','advanced','What is a free list?',ARRAY['Pool of available physical registers','List of free cache lines','List of free buses','List of free instructions'],0,'Free list: physical registers not currently in use.',20),
('cpu-boss','advanced','What is an architectural register file?',ARRAY['Registers visible to the programmer','Physical registers','Cache','Memory'],0,'ARF: ISA-defined registers (e.g., 32 GPRs in MIPS).',20),
('cpu-boss','advanced','What is the difference between PRF and ARF?',ARRAY['PRF has more for renaming; ARF is ISA-visible','No difference','PRF is smaller','ARF is larger'],0,'PRF: many physical. ARF: architectural (ISA-defined).',20),
('cpu-boss','advanced','What is a checkpoint in speculative execution?',ARRAY['Saved state for rollback on misprediction','Cache checkpoint','Memory checkpoint','Bus checkpoint'],0,'Checkpoint: save PRF mapping for branch recovery.',20),
('cpu-boss','advanced','What is a misprediction penalty?',ARRAY['Cycles lost when branch predicted wrong','Cache miss penalty','TLB miss penalty','Bus penalty'],0,'Misprediction: flush pipeline, restart from correct path.',20),
('cpu-boss','advanced','What is the branch misprediction rate of a good predictor?',ARRAY['< 1%','~50%','~10%','~25%'],0,'Modern predictors: 95-99% accuracy.',20),
('cpu-boss','advanced','What is a perceptron branch predictor?',ARRAY['ML-based predictor using weighted history','Simple counter','Random','Static'],0,'Perceptron: learns correlations, high accuracy.',20),
('cpu-boss','advanced','What is a tournament predictor?',ARRAY['Chooses between global and local predictors','Single predictor','No prediction','Random'],0,'Tournament: meta-predictor selects best predictor.',20),
('cpu-boss','advanced','What is a return address stack (RAS)?',ARRAY['Predicts return targets for function calls','Branch predictor','Cache predictor','Data predictor'],0,'RAS: push on call, pop on return, predicts return address.',20),
('cpu-boss','advanced','What is a hardware prefetcher?',ARRAY['Predicts and fetches data before needed','Branch predictor','Cache predictor','TLB predictor'],0,'Prefetcher: spatial/stride/stream pattern detection.',20),
('cpu-boss','advanced','What is a stride prefetcher?',ARRAY['Prefetches at constant address stride','Random prefetch','No prefetch','Sequential only'],0,'Stride: detects linear access patterns (e.g., a[i]).',20),
('cpu-boss','advanced','What is a stream prefetcher?',ARRAY['Prefetches sequential cache lines','Stride prefetch','No prefetch','Random prefetch'],0,'Stream: detects sequential access, prefetches ahead.',20),
('cpu-boss','advanced','What is a memory-level parallelism (MLP)?',ARRAY['Multiple outstanding memory requests','Instruction parallelism','Thread parallelism','Data parallelism'],0,'MLP: number of cache misses served simultaneously.',20),
('cpu-boss','advanced','What is a non-blocking cache?',ARRAY['Serves other requests during a miss','Blocks on miss','No cache','Write-only cache'],0,'Non-blocking (lockup-free): continues on miss.',20),
('cpu-boss','advanced','What is a hardware prefetching for instruction fetch?',ARRAY['Prefetches next instruction cache lines','Data prefetch','No prefetch','Random prefetch'],0,'Instruction prefetch: sequential fetch pattern.',20),
('cpu-boss','advanced','What is a power gating in CPU?',ARRAY['Cutting power to idle components','Clock gating only','Bus gating','Cache gating'],0,'Power gating: reduces leakage power in idle units.',20),
('cpu-boss','advanced','What is dynamic voltage and frequency scaling (DVFS)?',ARRAY['Adjusting V/f for power-performance trade-off','Fixed voltage','Fixed frequency','No scaling'],0,'DVFS: lower V/f when performance not needed.',20),
